-- Session 11 (D-80, P-185, P-186, P-191, P-193). Generated by drizzle-kit, the
-- GRANTs at the end added by hand.
--
-- Two credentials that are not OpenBao tokens. Neither secret is stored: each
-- row holds a keyed digest of it (`verifier`, 32 bytes) and the id of the key.
--
-- * app.automation_credential: what a provisioner presents. `owner_id` is the
--   first credential of its chain (its own id when it replaces none), and
--   app.project.managed_by names a chain, so a replacement manages the same
--   projects. The API may change state, last_used_at and revoked_at only.
-- * app.machine_credential gains kind 'runtime': a verifier and never an
--   accessor. Every row written before this migration reads kind 'token',
--   issued_by_kind 'user' and no bound address. The five new columns are
--   written at insert: the API has no UPDATE on them (0001 grants by column).
-- * app.project.managed_by is written at insert only, for the same reason.
-- * A version event may name a machine actor (an automation credential).
CREATE TABLE "app"."automation_credential" (
	"id" uuid PRIMARY KEY NOT NULL,
	"organization_id" uuid NOT NULL,
	"owner_id" uuid NOT NULL,
	"name" text NOT NULL,
	"rights" text[] NOT NULL,
	"bound_cidrs" text[] NOT NULL,
	"verifier" "bytea" NOT NULL,
	"verifier_key_id" text NOT NULL,
	"state" text NOT NULL,
	"expires_at" timestamp with time zone NOT NULL,
	"issued_by" uuid NOT NULL,
	"issuance_operation_id" uuid NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"last_used_at" timestamp with time zone,
	"revoked_at" timestamp with time zone,
	CONSTRAINT "automation_credential_organization_id_key" UNIQUE("organization_id","id"),
	CONSTRAINT "automation_credential_state_check" CHECK ("app"."automation_credential"."state" in ('active', 'revoked')),
	CONSTRAINT "automation_credential_rights_check" CHECK (cardinality("app"."automation_credential"."rights") between 1 and 3 and "app"."automation_credential"."rights" <@ array['projects.create', 'secrets.create', 'runtime_credentials.manage']::text[]),
	CONSTRAINT "automation_credential_cidrs_check" CHECK (cardinality("app"."automation_credential"."bound_cidrs") between 1 and 8),
	CONSTRAINT "automation_credential_name_length_check" CHECK (char_length("app"."automation_credential"."name") between 1 and 64),
	CONSTRAINT "automation_credential_verifier_check" CHECK (octet_length("app"."automation_credential"."verifier") = 32)
);
